feed:
Jekyll


{{ site.time | date_to_xmlschema }}
{{ page.url | absolute_url | xml_escape }}
{%- assign feed_title = site.title %}
{%- if include.label %}{% assign feed_title = feed_title | append: " (" | append: include.label | append: ")" %}{% endif %}
{{ feed_title | smartify | xml_escape }}
{{ site.description | xml_escape }}

  {{ site.title | xml_escape }}


{%- assign posts = site.posts | where_exp: "post", "post.archived != true" | where_exp: "post", "post.draft != true" %}
{%- if include.topic %}{% assign posts = posts | where: "topic", include.topic %}{% endif %}
{%- assign posts_limit = site.feed.posts_limit | default: 10 %}
{%- for post in posts limit: posts_limit %}
{%- assign post_title = post.title | smartify | strip_html | normalize_whitespace | xml_escape %}
{%- comment -%} Same authors:/author: handling as _includes/author-byline.html. {%- endcomment -%}
{%- if post.authors %}
  {%- assign post_authors = post.authors %}
{%- else %}
  {%- assign post_authors = post.author | split: "|" %}
{%- endif %}
{%- assign post_summary = post.description | default: post.excerpt %}

  {{ post_title }}

  {{ post.date | date_to_xmlschema }}
  {{ post.last_modified_at | default: post.date | date_to_xmlschema }}
  {{ post.id | absolute_url | xml_escape }}
  {{ post.content | strip }}
  {%- for post_author in post_authors %}

    {{ post_author | xml_escape }}

  {%- endfor %}

  {%- for tag in post.tags %}

  {%- endfor %}
  {%- if post_summary and post_summary != empty %}
  {{ post_summary | strip_html | normalize_whitespace }}
  {%- endif %}

{%- endfor %}
